SELECT SUM(i.amount) AS billed
FROM school.invoices i
LEFT JOIN school.payments p ON p.invoice_id = i.invoice_id;

SELECT i.invoice_id FROM school.invoices i
WHERE NOT EXISTS (
  SELECT 1 FROM school.payments p
  WHERE /* korelasi invoice dan filter status */
)
ORDER BY i.invoice_id;

SELECT i.invoice_id, i.amount - COALESCE(p.amount, 0.00) AS outstanding
FROM school.invoices i LEFT JOIN school.payments p ON p.invoice_id = i.invoice_id
ORDER BY i.invoice_id;
